                  "calibration_samples": len(calibration), "calibration_excludes_holdout": True}
    return {"model": final, "band": band, "validation": validation, "training_rows": len(x),
            "audit": {"outer_folds": outer_records, "final_selection": selection,
                      "selected_challenger": chosen, "published_model": published,
                      "selection_last_outcome_position": int(positions[train][-1] + horizon),
                      "deployment_rule": "freeze family before final holdout, publish only if it beats zero-return, then refit same family on observed labels",
                      "calibration_last_outcome_position": calibration_last_outcome,
                      "final_features": final.transform.names if final.transform else [],
                      "training_last_outcome_position": int(positions[-1] + horizon)}}


def build_models(frame, features, horizons, intraday, progress=None):
    models = {}
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        for horizon in horizons:
            if progress:
                progress("validation")
            models[horizon] = fit_horizon(frame, features, horizon, intraday)
    return models
